34|/* ===========================================================================
35| * Test deflate() with full flush
36| */
37|int test_flush(unsigned char *compr, z_size_t *comprLen) {
38|  z_stream c_stream; /* compression stream */
39|  int err;
40|  unsigned int len = dataLen;
41|
42|  c_stream.zalloc = zalloc;
43|  c_stream.zfree = zfree;
44|  c_stream.opaque = (void *)0;
45|
46|  err = deflateInit(&c_stream, Z_DEFAULT_COMPRESSION);
47|  CHECK_ERR(err, "deflateInit");
48|
49|  c_stream.next_in = (Bytef *)data;
50|  c_stream.next_out = compr;
51|  c_stream.avail_in = 3;
52|  c_stream.avail_out = (unsigned int)*comprLen;
53|  err = deflate(&c_stream, Z_FULL_FLUSH);
54|  CHECK_ERR(err, "deflate flush 1");
55|
56|  compr[3]++; /* force an error in first compressed block */
57|  c_stream.avail_in = len - 3;
58|
59|  err = deflate(&c_stream, Z_FINISH);
60|  if (err != Z_STREAM_END) {
61|    CHECK_ERR(err, "deflate flush 2");
62|  }
63|  err = deflateEnd(&c_stream);
64|  CHECK_ERR(err, "deflateEnd");
65|
66|  *comprLen = (z_size_t)c_stream.total_out;
67|
68|  return 0;
69|}
