71|/* ===========================================================================
72| * Test inflateSync()
73| */
74|int test_sync(unsigned char *compr, size_t comprLen, unsigned char *uncompr,
75|               size_t uncomprLen) {
76|  int err;
77|  z_stream d_stream; /* decompression stream */
78|
79|  d_stream.zalloc = zalloc;
80|  d_stream.zfree = zfree;
81|  d_stream.opaque = (void *)0;
82|
83|  d_stream.next_in = compr;
84|  d_stream.avail_in = 2; /* just read the zlib header */
85|
86|  err = inflateInit(&d_stream);
87|  CHECK_ERR(err, "inflateInit");
88|
89|  d_stream.next_out = uncompr;
90|  d_stream.avail_out = (unsigned int)uncomprLen;
91|
92|  err = inflate(&d_stream, Z_NO_FLUSH);
93|  CHECK_ERR(err, "inflate");
94|
95|  d_stream.avail_in = (unsigned int)comprLen - 2; /* read all compressed data */
96|  err = inflateSync(&d_stream); /* but skip the damaged part */
97|  CHECK_ERR(err, "inflateSync");
98|
99|  err = inflate(&d_stream, Z_FINISH);
100|  if (err != Z_DATA_ERROR && err != Z_STREAM_END) {
101|    fprintf(stderr, "inflate should report DATA_ERROR or Z_STREAM_END\n");
102|    /* v1.1.11= reports DATA_ERROR because of incorrect adler32. v1.1.12+ reports Z_STREAM END because it skips the adler32 check. */
103|    return 0;
104|  }
105|  err = inflateEnd(&d_stream);
106|  CHECK_ERR(err, "inflateEnd");
107|  return 0;
108|}
