110|int LLVMFuzzerTestOneInput(const uint8_t *d, size_t size) {
111|  size_t comprLen = 100 + 2 * compressBound(size);
112|  size_t uncomprLen = size;
113|  uint8_t *compr, *uncompr;
114|
115|  /* Discard inputs larger than 1Mb. */
116|  static size_t kMaxSize = 1024 * 1024;
117|
118|  // This test requires at least 3 bytes of input data.
119|  if (size <= 3 || size > kMaxSize)
120|    return 0;
121|
122|  data = d;
123|  dataLen = size;
124|  compr = (uint8_t *)calloc(1, comprLen);
125|  uncompr = (uint8_t *)calloc(1, uncomprLen);
126|
127|  test_flush(compr, &comprLen);
128|  test_sync(compr, comprLen, uncompr, uncomprLen);
129|
130|  free(compr);
131|  free(uncompr);
132|
133|  /* This function must return 0. */
134|  return 0;
135|}

387|int ZEXPORT deflateInit2_(z_streamp strm, int level, int method,
388|                          int windowBits, int memLevel, int strategy,
389|                          const char *version, int stream_size) {
390|    deflate_state *s;
391|    int wrap = 1;
392|    static const char my_version[] = ZLIB_VERSION;
393|
394|    if (version == Z_NULL || version[0] != my_version[0] ||
395|        stream_size != sizeof(z_stream)) {
396|        return Z_VERSION_ERROR;
397|    }
398|    if (strm == Z_NULL) return Z_STREAM_ERROR;
399|
400|    strm->msg = Z_NULL;
401|    if (strm->zalloc == (alloc_func)0) {
402|#ifdef Z_SOLO
403|        return Z_STREAM_ERROR;
404|#else
405|        strm->zalloc = zcalloc;
406|        strm->opaque = (voidpf)0;
407|#endif
408|    }
409|    if (strm->zfree == (free_func)0)
410|#ifdef Z_SOLO
411|        return Z_STREAM_ERROR;
412|#else
413|        strm->zfree = zcfree;
414|#endif
415|
416|#ifdef FASTEST
417|    if (level != 0) level = 1;
418|#else
419|    if (level == Z_DEFAULT_COMPRESSION) level = 6;
420|#endif
421|
422|    if (windowBits < 0) { /* suppress zlib wrapper */
423|        wrap = 0;
424|        if (windowBits < -15)
425|            return Z_STREAM_ERROR;
426|        windowBits = -windowBits;
427|    }
428|#ifdef GZIP
429|    else if (windowBits > 15) {
430|        wrap = 2;       /* write gzip wrapper instead */
431|        windowBits -= 16;
432|    }
433|#endif
434|    if (memLevel < 1 || memLevel > MAX_MEM_LEVEL || method != Z_DEFLATED ||
435|        windowBits < 8 || windowBits > 15 || level < 0 || level > 9 ||
436|        strategy < 0 || strategy > Z_FIXED || (windowBits == 8 && wrap != 1)) {
437|        return Z_STREAM_ERROR;
438|    }
439|    if (windowBits == 8) windowBits = 9;  /* until 256-byte window bug fixed */
440|    s = (deflate_state *) ZALLOC(strm, 1, sizeof(deflate_state));
441|    if (s == Z_NULL) return Z_MEM_ERROR;
442|    zmemzero(s, sizeof(deflate_state));
443|    strm->state = (struct internal_state FAR *)s;
444|    s->strm = strm;
445|    s->status = INIT_STATE;     /* to pass state test in deflateReset() */
446|
447|    s->wrap = wrap;
448|    s->w_bits = (uInt)windowBits;
449|    s->w_size = 1 << s->w_bits;
450|    s->w_mask = s->w_size - 1;
451|
452|    s->hash_bits = (uInt)memLevel + 7;
453|    s->hash_size = 1 << s->hash_bits;
454|    s->hash_mask = s->hash_size - 1;
455|    s->hash_shift =  ((s->hash_bits + MIN_MATCH-1) / MIN_MATCH);
456|
457|    s->window = (Bytef *) ZALLOC(strm, s->w_size, 2*sizeof(Byte));
458|    s->prev   = (Posf *)  ZALLOC(strm, s->w_size, sizeof(Pos));
459|    s->head   = (Posf *)  ZALLOC(strm, s->hash_size, sizeof(Pos));
460|
461|    s->high_water = 0;      /* nothing written to s->window yet */
462|
463|    s->lit_bufsize = 1 << (memLevel + 6); /* 16K elements by default */
464|
465|    /* We overlay pending_buf and sym_buf. This works since the average size
466|     * for length/distance pairs over any compressed block is assured to be 31
467|     * bits or less.
468|     *
469|     * Analysis: The longest fixed codes are a length code of 8 bits plus 5
470|     * extra bits, for lengths 131 to 257. The longest fixed distance codes are
471|     * 5 bits plus 13 extra bits, for distances 16385 to 32768. The longest
472|     * possible fixed-codes length/distance pair is then 31 bits total.
473|     *
474|     * sym_buf starts one-fourth of the way into pending_buf. So there are
475|     * three bytes in sym_buf for every four bytes in pending_buf. Each symbol
476|     * in sym_buf is three bytes -- two for the distance and one for the
477|     * literal/length. As each symbol is consumed, the pointer to the next
478|     * sym_buf value to read moves forward three bytes. From that symbol, up to
479|     * 31 bits are written to pending_buf. The closest the written pending_buf
480|     * bits gets to the next sym_buf symbol to read is just before the last
481|     * code is written. At that time, 31*(n - 2) bits have been written, just
482|     * after 24*(n - 2) bits have been consumed from sym_buf. sym_buf starts at
483|     * 8*n bits into pending_buf. (Note that the symbol buffer fills when n - 1
484|     * symbols are written.) The closest the writing gets to what is unread is
485|     * then n + 14 bits. Here n is lit_bufsize, which is 16384 by default, and
486|     * can range from 128 to 32768.
487|     *
488|     * Therefore, at a minimum, there are 142 bits of space between what is
489|     * written and what is read in the overlain buffers, so the symbols cannot
490|     * be overwritten by the compressed data. That space is actually 139 bits,
491|     * due to the three-bit fixed-code block header.
492|     *
493|     * That covers the case where either Z_FIXED is specified, forcing fixed
494|     * codes, or when the use of fixed codes is chosen, because that choice
495|     * results in a smaller compressed block than dynamic codes. That latter
496|     * condition then assures that the above analysis also covers all dynamic
497|     * blocks. A dynamic-code block will only be chosen to be emitted if it has
498|     * fewer bits than a fixed-code block would for the same set of symbols.
499|     * Therefore its average symbol length is assured to be less than 31. So
500|     * the compressed data for a dynamic block also cannot overwrite the
501|     * symbols from which it is being constructed.
502|     */
503|
504|    s->pending_buf = (uchf *) ZALLOC(strm, s->lit_bufsize, LIT_BUFS);
505|    s->pending_buf_size = (ulg)s->lit_bufsize * 4;
506|
507|    if (s->window == Z_NULL || s->prev == Z_NULL || s->head == Z_NULL ||
508|        s->pending_buf == Z_NULL) {
509|        s->status = FINISH_STATE;
510|        strm->msg = ERR_MSG(Z_MEM_ERROR);
511|        deflateEnd (strm);
512|        return Z_MEM_ERROR;
513|    }
514|#ifdef LIT_MEM
515|    s->d_buf = (ushf *)(s->pending_buf + (s->lit_bufsize << 1));
516|    s->l_buf = s->pending_buf + (s->lit_bufsize << 2);
517|    s->sym_end = s->lit_bufsize - 1;
518|#else
519|    s->sym_buf = s->pending_buf + s->lit_bufsize;
520|    s->sym_end = (s->lit_bufsize - 1) * 3;
521|#endif
522|    /* We avoid equality with lit_bufsize*3 because of wraparound at 64K
523|     * on 16 bit machines and because stored blocks are restricted to
524|     * 64K-1 bytes.
525|     */
526|
527|    s->level = level;
528|    s->strategy = strategy;
529|    s->method = (Byte)method;
530|
531|    return deflateReset(strm);
532|}

379|int ZEXPORT deflateInit_(z_streamp strm, int level, const char *version,
380|                         int stream_size) {
381|    return deflateInit2_(strm, level, Z_DEFLATED, MAX_WBITS, DEF_MEM_LEVEL,
382|                         Z_DEFAULT_STRATEGY, version, stream_size);
383|    /* To do: ignore strm->next_in if we use it as window */
384|}

982|int ZEXPORT deflate(z_streamp strm, int flush) {
983|    int old_flush; /* value of flush param for previous deflate call */
984|    deflate_state *s;
985|
986|    if (deflateStateCheck(strm) || flush > Z_BLOCK || flush < 0) {
987|        return Z_STREAM_ERROR;
988|    }
989|    s = strm->state;
990|
991|    if (strm->next_out == Z_NULL ||
992|        (strm->avail_in != 0 && strm->next_in == Z_NULL) ||
993|        (s->status == FINISH_STATE && flush != Z_FINISH)) {
994|        ERR_RETURN(strm, Z_STREAM_ERROR);
995|    }
996|    if (strm->avail_out == 0) ERR_RETURN(strm, Z_BUF_ERROR);
997|
998|    old_flush = s->last_flush;
999|    s->last_flush = flush;
1000|
1001|    /* Flush as much pending output as possible */
1002|    if (s->pending != 0) {
1003|        flush_pending(strm);
1004|        if (strm->avail_out == 0) {
1005|            /* Since avail_out is 0, deflate will be called again with
1006|             * more output space, but possibly with both pending and
1007|             * avail_in equal to zero. There won't be anything to do,
1008|             * but this is not an error situation so make sure we
1009|             * return OK instead of BUF_ERROR at next call of deflate:
1010|             */
1011|            s->last_flush = -1;
1012|            return Z_OK;
1013|        }
1014|
1015|    /* Make sure there is something to do and avoid duplicate consecutive
1016|     * flushes. For repeated and useless calls with Z_FINISH, we keep
1017|     * returning Z_STREAM_END instead of Z_BUF_ERROR.
1018|     */
1019|    } else if (strm->avail_in == 0 && RANK(flush) <= RANK(old_flush) &&
1020|               flush != Z_FINISH) {
1021|        ERR_RETURN(strm, Z_BUF_ERROR);
1022|    }
1023|
1024|    /* User must not provide more input after the first FINISH: */
1025|    if (s->status == FINISH_STATE && strm->avail_in != 0) {
1026|        ERR_RETURN(strm, Z_BUF_ERROR);
1027|    }
1028|
1029|    /* Write the header */
1030|    if (s->status == INIT_STATE && s->wrap == 0)
1031|        s->status = BUSY_STATE;
1032|    if (s->status == INIT_STATE) {
1033|        /* zlib header */
1034|        uInt header = (Z_DEFLATED + ((s->w_bits - 8) << 4)) << 8;
1035|        uInt level_flags;
1036|
1037|        if (s->strategy >= Z_HUFFMAN_ONLY || s->level < 2)
1038|            level_flags = 0;
1039|        else if (s->level < 6)
1040|            level_flags = 1;
1041|        else if (s->level == 6)
1042|            level_flags = 2;
1043|        else
1044|            level_flags = 3;
1045|        header |= (level_flags << 6);
1046|        if (s->strstart != 0) header |= PRESET_DICT;
1047|        header += 31 - (header % 31);
1048|
1049|        putShortMSB(s, header);
1050|
1051|        /* Save the adler32 of the preset dictionary: */
1052|        if (s->strstart != 0) {
1053|            putShortMSB(s, (uInt)(strm->adler >> 16));
1054|            putShortMSB(s, (uInt)(strm->adler & 0xffff));
1055|        }
1056|        strm->adler = adler32(0L, Z_NULL, 0);
1057|        s->status = BUSY_STATE;
1058|
1059|        /* Compression must start with an empty pending buffer */
1060|        flush_pending(strm);
1061|        if (s->pending != 0) {
1062|            s->last_flush = -1;
1063|            return Z_OK;
1064|        }
1065|    }
1066|#ifdef GZIP
1067|    if (s->status == GZIP_STATE) {
1068|        /* gzip header */
1069|        strm->adler = crc32(0L, Z_NULL, 0);
1070|        put_byte(s, 31);
1071|        put_byte(s, 139);
1072|        put_byte(s, 8);
1073|        if (s->gzhead == Z_NULL) {
1074|            put_byte(s, 0);
1075|            put_byte(s, 0);
1076|            put_byte(s, 0);
1077|            put_byte(s, 0);
1078|            put_byte(s, 0);
1079|            put_byte(s, s->level == 9 ? 2 :
1080|                     (s->strategy >= Z_HUFFMAN_ONLY || s->level < 2 ?
1081|                      4 : 0));
1082|            put_byte(s, OS_CODE);
1083|            s->status = BUSY_STATE;
1084|
1085|            /* Compression must start with an empty pending buffer */
1086|            flush_pending(strm);
1087|            if (s->pending != 0) {
1088|                s->last_flush = -1;
1089|                return Z_OK;
1090|            }
1091|        }
1092|        else {
1093|            put_byte(s, (s->gzhead->text ? 1 : 0) +
1094|                     (s->gzhead->hcrc ? 2 : 0) +
1095|                     (s->gzhead->extra == Z_NULL ? 0 : 4) +
1096|                     (s->gzhead->name == Z_NULL ? 0 : 8) +
1097|                     (s->gzhead->comment == Z_NULL ? 0 : 16)
1098|                     );
1099|            put_byte(s, (Byte)(s->gzhead->time & 0xff));
1100|            put_byte(s, (Byte)((s->gzhead->time >> 8) & 0xff));
1101|            put_byte(s, (Byte)((s->gzhead->time >> 16) & 0xff));
1102|            put_byte(s, (Byte)((s->gzhead->time >> 24) & 0xff));
1103|            put_byte(s, s->level == 9 ? 2 :
1104|                     (s->strategy >= Z_HUFFMAN_ONLY || s->level < 2 ?
1105|                      4 : 0));
1106|            put_byte(s, s->gzhead->os & 0xff);
1107|            if (s->gzhead->extra != Z_NULL) {
1108|                put_byte(s, s->gzhead->extra_len & 0xff);
1109|                put_byte(s, (s->gzhead->extra_len >> 8) & 0xff);
1110|            }
1111|            if (s->gzhead->hcrc)
1112|                strm->adler = crc32_z(strm->adler, s->pending_buf,
1113|                                      s->pending);
1114|            s->gzindex = 0;
1115|            s->status = EXTRA_STATE;
1116|        }
1117|    }
1118|    if (s->status == EXTRA_STATE) {
1119|        if (s->gzhead->extra != Z_NULL) {
1120|            ulg beg = s->pending;   /* start of bytes to update crc */
1121|            ulg left = (s->gzhead->extra_len & 0xffff) - s->gzindex;
1122|            while (s->pending + left > s->pending_buf_size) {
1123|                ulg copy = s->pending_buf_size - s->pending;
1124|                zmemcpy(s->pending_buf + s->pending,
1125|                        s->gzhead->extra + s->gzindex, copy);
1126|                s->pending = s->pending_buf_size;
1127|                HCRC_UPDATE(beg);
1128|                s->gzindex += copy;
1129|                flush_pending(strm);
1130|                if (s->pending != 0) {
1131|                    s->last_flush = -1;
1132|                    return Z_OK;
1133|                }
1134|                beg = 0;
1135|                left -= copy;
1136|            }
1137|            zmemcpy(s->pending_buf + s->pending,
1138|                    s->gzhead->extra + s->gzindex, left);
1139|            s->pending += left;
1140|            HCRC_UPDATE(beg);
1141|            s->gzindex = 0;
1142|        }
1143|        s->status = NAME_STATE;
1144|    }
1145|    if (s->status == NAME_STATE) {
1146|        if (s->gzhead->name != Z_NULL) {
1147|            ulg beg = s->pending;   /* start of bytes to update crc */
1148|            int val;
1149|            do {
1150|                if (s->pending == s->pending_buf_size) {
1151|                    HCRC_UPDATE(beg);
1152|                    flush_pending(strm);
1153|                    if (s->pending != 0) {
1154|                        s->last_flush = -1;
1155|                        return Z_OK;
1156|                    }
1157|                    beg = 0;
1158|                }
1159|                val = s->gzhead->name[s->gzindex++];
1160|                put_byte(s, val);
1161|            } while (val != 0);
1162|            HCRC_UPDATE(beg);
1163|            s->gzindex = 0;
1164|        }
1165|        s->status = COMMENT_STATE;
1166|    }
1167|    if (s->status == COMMENT_STATE) {
1168|        if (s->gzhead->comment != Z_NULL) {
1169|            ulg beg = s->pending;   /* start of bytes to update crc */
1170|            int val;
1171|            do {
1172|                if (s->pending == s->pending_buf_size) {
1173|                    HCRC_UPDATE(beg);
1174|                    flush_pending(strm);
1175|                    if (s->pending != 0) {
1176|                        s->last_flush = -1;
1177|                        return Z_OK;
1178|                    }
1179|                    beg = 0;
1180|                }
1181|                val = s->gzhead->comment[s->gzindex++];
1182|                put_byte(s, val);
1183|            } while (val != 0);
1184|            HCRC_UPDATE(beg);
1185|        }
1186|        s->status = HCRC_STATE;
1187|    }
1188|    if (s->status == HCRC_STATE) {
1189|        if (s->gzhead->hcrc) {
1190|            if (s->pending + 2 > s->pending_buf_size) {
1191|                flush_pending(strm);
1192|                if (s->pending != 0) {
1193|                    s->last_flush = -1;
1194|                    return Z_OK;
1195|                }
1196|            }
1197|            put_byte(s, (Byte)(strm->adler & 0xff));
1198|            put_byte(s, (Byte)((strm->adler >> 8) & 0xff));
1199|            strm->adler = crc32(0L, Z_NULL, 0);
1200|        }
1201|        s->status = BUSY_STATE;
1202|
1203|        /* Compression must start with an empty pending buffer */
1204|        flush_pending(strm);
1205|        if (s->pending != 0) {
1206|            s->last_flush = -1;
1207|            return Z_OK;
1208|        }
1209|    }
1210|#endif
1211|
1212|    /* Start a new block or continue the current one.
1213|     */
1214|    if (strm->avail_in != 0 || s->lookahead != 0 ||
1215|        (flush != Z_NO_FLUSH && s->status != FINISH_STATE)) {
1216|        block_state bstate;
1217|
1218|        bstate = s->level == 0 ? deflate_stored(s, flush) :
1219|                 s->strategy == Z_HUFFMAN_ONLY ? deflate_huff(s, flush) :
1220|                 s->strategy == Z_RLE ? deflate_rle(s, flush) :
1221|                 (*(configuration_table[s->level].func))(s, flush);
1222|
1223|        if (bstate == finish_started || bstate == finish_done) {
1224|            s->status = FINISH_STATE;
1225|        }
1226|        if (bstate == need_more || bstate == finish_started) {
1227|            if (strm->avail_out == 0) {
1228|                s->last_flush = -1; /* avoid BUF_ERROR next call, see above */
1229|            }
1230|            return Z_OK;
1231|            /* If flush != Z_NO_FLUSH && avail_out == 0, the next call
1232|             * of deflate should use the same flush parameter to make sure
1233|             * that the flush is complete. So we don't have to output an
1234|             * empty block here, this will be done at next call. This also
1235|             * ensures that for a very small output buffer, we emit at most
1236|             * one empty block.
1237|             */
1238|        }
1239|        if (bstate == block_done) {
1240|            if (flush == Z_PARTIAL_FLUSH) {
1241|                _tr_align(s);
1242|            } else if (flush != Z_BLOCK) { /* FULL_FLUSH or SYNC_FLUSH */
1243|                _tr_stored_block(s, (char*)0, 0L, 0);
