212|/* ===========================================================================
213| * Read a new buffer from the current input stream, update the adler32
214| * and total number of bytes read.  All deflate() input goes through
215| * this function so some applications may wish to modify it to avoid
216| * allocating a large strm->next_in buffer and copying from it.
217| * (See also flush_pending()).
218| */
219|local unsigned read_buf(z_streamp strm, Bytef *buf, unsigned size) {
220|    unsigned len = strm->avail_in;
221|
222|    if (len > size) len = size;
223|    if (len == 0) return 0;
224|
225|    strm->avail_in  -= len;
226|
227|    zmemcpy(buf, strm->next_in, len);
228|    if (strm->state->wrap == 1) {
229|        strm->adler = adler32(strm->adler, buf, len);
230|    }
231|#ifdef GZIP
232|    else if (strm->state->wrap == 2) {
233|        strm->adler = crc32(strm->adler, buf, len);
234|    }
235|#endif
236|    strm->next_in  += len;
237|    strm->total_in += len;
238|
239|    return len;
