1381|/* ===========================================================================
1382| * Set match_start to the longest match starting at the given string and
1383| * return its length. Matches shorter or equal to prev_length are discarded,
1384| * in which case the result is equal to prev_length and match_start is
1385| * garbage.
1386| * IN assertions: cur_match is the head of the hash chain for the current
1387| *   string (strstart) and its distance is <= MAX_DIST, and prev_length >= 1
1388| * OUT assertion: the match length is not greater than s->lookahead.
1389| */
1390|local uInt longest_match(deflate_state *s, IPos cur_match) {
1391|    unsigned chain_length = s->max_chain_length;/* max hash chain length */
1392|    Bytef *scan = s->window + s->strstart;      /* current string */
1393|    Bytef *match;                               /* matched string */
1394|    int len;                                    /* length of current match */
1395|    int best_len = (int)s->prev_length;         /* best match length so far */
1396|    int nice_match = s->nice_match;             /* stop if match long enough */
1397|    IPos limit = s->strstart > (IPos)MAX_DIST(s) ?
1398|        s->strstart - (IPos)MAX_DIST(s) : NIL;
1399|    /* Stop when cur_match becomes <= limit. To simplify the code,
1400|     * we prevent matches with the string of window index 0.
1401|     */
1402|    Posf *prev = s->prev;
1403|    uInt wmask = s->w_mask;
1404|
1405|#ifdef UNALIGNED_OK
1406|    /* Compare two bytes at a time. Note: this is not always beneficial.
1407|     * Try with and without -DUNALIGNED_OK to check.
1408|     */
1409|    Bytef *strend = s->window + s->strstart + MAX_MATCH - 1;
1410|    ush scan_start = *(ushf*)scan;
1411|    ush scan_end   = *(ushf*)(scan + best_len - 1);
1412|#else
1413|    Bytef *strend = s->window + s->strstart + MAX_MATCH;
1414|    Byte scan_end1  = scan[best_len - 1];
1415|    Byte scan_end   = scan[best_len];
1416|#endif
1417|
1418|    /* The code is optimized for HASH_BITS >= 8 and MAX_MATCH-2 multiple of 16.
1419|     * It is easy to get rid of this optimization if necessary.
1420|     */
1421|    Assert(s->hash_bits >= 8 && MAX_MATCH == 258, "Code too clever");
1422|
1423|    /* Do not waste too much time if we already have a good match: */
1424|    if (s->prev_length >= s->good_match) {
1425|        chain_length >>= 2;
1426|    }
