1458|         * lookahead only every 4th comparison; the 128th check will be made
1459|         * at strstart + 257. If MAX_MATCH-2 is not a multiple of 8, it is
1460|         * necessary to put more guard bytes at the end of the window, or
1461|         * to check more often for insufficient lookahead.
1462|         */
1463|        Assert(scan[2] == match[2], "scan[2]?");
1464|        scan++, match++;
