1466|        } while (*(ushf*)(scan += 2) == *(ushf*)(match += 2) &&
1467|                 *(ushf*)(scan += 2) == *(ushf*)(match += 2) &&
1468|                 *(ushf*)(scan += 2) == *(ushf*)(match += 2) &&
1469|                 *(ushf*)(scan += 2) == *(ushf*)(match += 2) &&
1470|                 scan < strend);
