1501|        } while (*++scan == *++match && *++scan == *++match &&
1502|                 *++scan == *++match && *++scan == *++match &&
1503|                 *++scan == *++match && *++scan == *++match &&
1504|                 *++scan == *++match && *++scan == *++match &&
1505|                 scan < strend);
