1507|        Assert(scan <= s->window + (unsigned)(s->window_size - 1),
1508|               "wild scan");
1509|
1510|        len = MAX_MATCH - (int)(strend - scan);
1511|        scan = strend - MAX_MATCH;
1512|
1513|#endif /* UNALIGNED_OK */
1514|
1515|        if (len > best_len) {
1516|            s->match_start = cur_match;
1517|            best_len = len;
1518|            if (len >= nice_match) break;
1519|#ifdef UNALIGNED_OK
1520|            scan_end = *(ushf*)(scan + best_len - 1);
1521|#else
1522|            scan_end1  = scan[best_len - 1];
1523|            scan_end   = scan[best_len];
1524|#endif
1525|        }
1526|    } while ((cur_match = prev[cur_match & wmask]) > limit
