301|#ifdef GUNZIP
302|#  define UPDATE_CHECK(check, buf, len) \
303|    (state->flags ? crc32(check, buf, len) : adler32(check, buf, len))
304|#else
305|#  define UPDATE_CHECK(check, buf, len) adler32(check, buf, len)
306|#endif
