93|int inf(FILE *source, FILE *dest)
94|{
95|    int ret;
96|    unsigned have;
97|    z_stream strm;
98|    unsigned char in[CHUNK];
99|    unsigned char out[CHUNK];
100|
101|    /* allocate inflate state */
102|    strm.zalloc = Z_NULL;
103|    strm.zfree = Z_NULL;
104|    strm.opaque = Z_NULL;
105|    strm.avail_in = 0;
106|    strm.next_in = Z_NULL;
107|    ret = inflateInit(&strm);
108|    if (ret != Z_OK)
109|        return ret;
110|
111|    /* decompress until deflate stream ends or end of file */
112|    do {
113|        strm.avail_in = fread(in, 1, CHUNK, source);
114|        if (ferror(source)) {
115|            (void)inflateEnd(&strm);
116|            return Z_ERRNO;
117|        }
118|        if (strm.avail_in == 0)
119|            break;
120|        strm.next_in = in;
121|
122|        /* run inflate() on input until output buffer not full */
123|        do {
124|            strm.avail_out = CHUNK;
125|            strm.next_out = out;
126|            ret = inflate(&strm, Z_NO_FLUSH);
127|            assert(ret != Z_STREAM_ERROR);  /* state not clobbered */
128|            switch (ret) {
129|            case Z_NEED_DICT:
130|                ret = Z_DATA_ERROR;     /* and fall through */
131|            case Z_DATA_ERROR:
132|            case Z_MEM_ERROR:
133|                (void)inflateEnd(&strm);
134|                return ret;
135|            }
136|            have = CHUNK - strm.avail_out;
137|            if (fwrite(out, 1, have, dest) != have || ferror(dest)) {
138|                (void)inflateEnd(&strm);
139|                return Z_ERRNO;
140|            }
141|        } while (strm.avail_out == 0);
142|
143|        /* done when inflate() says it's done */
144|    } while (ret != Z_STREAM_END);
145|
146|    /* clean up and return */
147|    (void)inflateEnd(&strm);
148|    return ret == Z_STREAM_END ? Z_OK : Z_DATA_ERROR;
149|}

