91|int main(int argc, char **argv)
92|{
93|    int ret, put = 0, fail = 0;
94|    unsigned skip = 0;
95|    char *arg, *name = NULL;
96|    unsigned char *source = NULL, *dest;
97|    size_t len = 0;
98|    unsigned long sourcelen, destlen;
99|
100|    /* process arguments */
101|    while (arg = *++argv, --argc)
102|        if (arg[0] == '-') {
103|            if (arg[1] == 'w' && arg[2] == 0)
104|                put = 1;
105|            else if (arg[1] == 'f' && arg[2] == 0)
106|                fail = 1, put = 1;
107|            else if (arg[1] >= '0' && arg[1] <= '9')
108|                skip = (unsigned)atoi(arg + 1);
109|            else {
110|                fprintf(stderr, "invalid option %s\n", arg);
111|                return 3;
112|            }
113|        }
114|        else if (name != NULL) {
115|            fprintf(stderr, "only one file name allowed\n");
116|            return 3;
117|        }
118|        else
119|            name = arg;
120|    source = load(name, &len);
121|    if (source == NULL) {
122|        fprintf(stderr, "memory allocation failure\n");
123|        return 4;
124|    }
125|    if (len == 0) {
126|        fprintf(stderr, "could not read %s, or it was empty\n",
127|                name == NULL ? "<stdin>" : name);
128|        free(source);
129|        return 3;
130|    }
131|    if (skip >= len) {
132|        fprintf(stderr, "skip request of %d leaves no input\n", skip);
133|        free(source);
134|        return 3;
135|    }
136|
137|    /* test inflate data with offset skip */
138|    len -= skip;
139|    sourcelen = (unsigned long)len;
140|    ret = puff(NIL, &destlen, source + skip, &sourcelen);
141|    if (ret)
142|        fprintf(stderr, "puff() failed with return code %d\n", ret);
143|    else {
144|        fprintf(stderr, "puff() succeeded uncompressing %lu bytes\n", destlen);
145|        if (sourcelen < len) fprintf(stderr, "%lu compressed bytes unused\n",
146|                                     len - sourcelen);
147|    }
148|
149|    /* if requested, inflate again and write decompressed data to stdout */
150|    if (put && ret == 0) {
151|        if (fail)
152|            destlen >>= 1;
153|        dest = malloc(destlen);
154|        if (dest == NULL) {
155|            fprintf(stderr, "memory allocation failure\n");
156|            free(source);
157|            return 4;
158|        }
159|        puff(dest, &destlen, source + skip, &sourcelen);
160|        SET_BINARY_MODE(stdout);
161|        fwrite(dest, 1, destlen, stdout);
162|        free(dest);
163|    }
164|
165|    /* clean up */
166|    free(source);
167|    return ret;
168|}

498|int main(int argc, char **argv) {
499|    // set up globals for cleanup()
500|    g.code = NULL;
501|    g.num = NULL;
502|    g.done = NULL;
503|    string_init(&g.out);
504|
505|    // get arguments -- default to the deflate literal/length code
506|    int syms = 286;
507|    g.root = 9;
508|    g.max = 15;
509|    if (argc > 1) {
510|        syms = atoi(argv[1]);
511|        if (argc > 2) {
512|            g.root = atoi(argv[2]);
513|            if (argc > 3)
514|                g.max = atoi(argv[3]);
515|        }
516|    }
517|    if (argc > 4 || syms < 2 || g.root < 1 || g.max < 1) {
518|        fputs("invalid arguments, need: [sym >= 2 [root >= 1 [max >= 1]]]\n",
519|              stderr);
520|        return 1;
521|    }
522|
523|    // if not restricting the code length, the longest is syms - 1
524|    if (g.max > syms - 1)
525|        g.max = syms - 1;
526|
527|    // determine the number of bits in a code_t
528|    int bits = 0;
529|    for (code_t word = 1; word; word <<= 1)
530|        bits++;
531|
532|    // make sure that the calculation of most will not overflow
533|    if (g.max > bits || (code_t)(syms - 2) >= ((code_t)-1 >> (g.max - 1))) {
534|        fputs("abort: code length too long for internal types\n", stderr);
535|        return 1;
536|    }
537|
538|    // reject impossible code requests
539|    if ((code_t)(syms - 1) > ((code_t)1 << g.max) - 1) {
540|        fprintf(stderr, "%d symbols cannot be coded in %d bits\n",
541|                syms, g.max);
542|        return 1;
543|    }
544|
545|    // allocate code vector
546|    g.code = calloc(g.max + 1, sizeof(int));
547|    assert(g.code != NULL && "out of memory");
548|
549|    // determine size of saved results array, checking for overflows,
550|    // allocate and clear the array (set all to zero with calloc())
551|    if (syms == 2)              // iff max == 1
552|        g.num = NULL;           // won't be saving any results
553|    else {
554|        g.size = syms >> 1;
555|        int n = (syms - 1) >> 1;
556|        assert(g.size <= (size_t)-1 / n && "overflow");
557|        g.size *= n;
558|        n = g.max - 1;
559|        assert(g.size <= (size_t)-1 / n && "overflow");
560|        g.size *= n;
561|        g.num = calloc(g.size, sizeof(big_t));
562|        assert(g.num != NULL && "out of memory");
563|    }
564|
565|    // count possible codes for all numbers of symbols, add up counts
566|    big_t sum = 0;
567|    for (int n = 2; n <= syms; n++) {
568|        big_t got = count(n, 2, 1);
569|        sum += got;
570|        assert(got != (big_t)-1 && sum >= got && "overflow");
571|    }
572|    printf("%"PRIbig" total codes for 2 to %d symbols", sum, syms);
573|    if (g.max < syms - 1)
574|        printf(" (%d-bit length limit)\n", g.max);
575|    else
576|        puts(" (no length limit)");
577|
578|    // allocate and clear done array for been_here()
579|    if (syms == 2)
580|        g.done = NULL;
581|    else {
582|        g.done = calloc(g.size, sizeof(struct tab));
583|        assert(g.done != NULL && "out of memory");
584|    }
585|
586|    // find and show maximum inflate table usage
587|    if (g.root > g.max)             // reduce root to max length
588|        g.root = g.max;
589|    if ((code_t)syms < ((code_t)1 << (g.root + 1)))
590|        enough(syms);
591|    else
592|        fputs("cannot handle minimum code lengths > root", stderr);
593|
594|    // done
595|    cleanup();
596|    return 0;
597|}

96|local int recompress(z_streamp inf, z_streamp def)
97|{
98|    int ret, flush;
99|    unsigned char raw[RAWLEN];
100|
101|    flush = Z_NO_FLUSH;
102|    do {
103|        /* decompress */
104|        inf->avail_out = RAWLEN;
105|        inf->next_out = raw;
106|        ret = inflate(inf, Z_NO_FLUSH);
107|        assert(ret != Z_STREAM_ERROR && ret != Z_DATA_ERROR &&
108|               ret != Z_NEED_DICT);
109|        if (ret == Z_MEM_ERROR)
110|            return ret;
111|
112|        /* compress what was decompressed until done or no room */
113|        def->avail_in = RAWLEN - inf->avail_out;
114|        def->next_in = raw;
115|        if (inf->avail_out != 0)
116|            flush = Z_FINISH;
117|        ret = deflate(def, flush);
118|        assert(ret != Z_STREAM_ERROR);
119|    } while (ret != Z_STREAM_END && def->avail_out != 0);
120|    return ret;
121|}

259|local int gzscan(char *name, z_stream *strm, int level)
260|{
261|    int ret, lastbit, left, full;
262|    unsigned have;
263|    unsigned long crc, tot;
264|    unsigned char *window;
265|    off_t lastoff, end;
266|    file gz;
267|
268|    /* open gzip file */
269|    gz.name = name;
270|    gz.fd = open(name, O_RDWR, 0);
271|    if (gz.fd == -1) bye("cannot open ", name);
272|    gz.buf = malloc(CHUNK);
273|    if (gz.buf == NULL) bye("out of memory", "");
274|    gz.size = LGCHUNK;
275|    gz.left = 0;
276|
277|    /* skip gzip header */
278|    gzheader(&gz);
279|
280|    /* prepare to decompress */
281|    window = malloc(DSIZE);
282|    if (window == NULL) bye("out of memory", "");
283|    strm->zalloc = Z_NULL;
284|    strm->zfree = Z_NULL;
285|    strm->opaque = Z_NULL;
286|    ret = inflateInit2(strm, -15);
287|    if (ret != Z_OK) bye("out of memory", " or library mismatch");
288|
289|    /* decompress the deflate stream, saving append information */
290|    lastbit = 0;
291|    lastoff = lseek(gz.fd, 0L, SEEK_CUR) - gz.left;
292|    left = 0;
293|    strm->avail_in = gz.left;
294|    strm->next_in = gz.next;
295|    crc = crc32(0L, Z_NULL, 0);
296|    have = full = 0;
297|    do {
298|        /* if needed, get more input */
299|        if (strm->avail_in == 0) {
300|            readmore(&gz);
301|            strm->avail_in = gz.left;
302|            strm->next_in = gz.next;
303|        }
304|
305|        /* set up output to next available section of sliding window */
306|        strm->avail_out = DSIZE - have;
307|        strm->next_out = window + have;
308|
309|        /* inflate and check for errors */
310|        ret = inflate(strm, Z_BLOCK);
311|        if (ret == Z_STREAM_ERROR) bye("internal stream error!", "");
312|        if (ret == Z_MEM_ERROR) bye("out of memory", "");
313|        if (ret == Z_DATA_ERROR)
314|            bye("invalid compressed data--format violated in", name);
315|
316|        /* update crc and sliding window pointer */
317|        crc = crc32(crc, window + have, DSIZE - have - strm->avail_out);
318|        if (strm->avail_out)
319|            have = DSIZE - strm->avail_out;
320|        else {
321|            have = 0;
322|            full = 1;
323|        }
324|
325|        /* process end of block */
326|        if (strm->data_type & 128) {
327|            if (strm->data_type & 64)
328|                left = strm->data_type & 0x1f;
329|            else {
330|                lastbit = strm->data_type & 0x1f;
331|                lastoff = lseek(gz.fd, 0L, SEEK_CUR) - strm->avail_in;
332|            }
333|        }
334|    } while (ret != Z_STREAM_END);
335|    inflateEnd(strm);
336|    gz.left = strm->avail_in;
337|    gz.next = strm->next_in;
