279|local void gzcopy(char *name, int clr, unsigned long *crc, unsigned long *tot,
280|                  FILE *out)
281|{
282|    int ret;                /* return value from zlib functions */
283|    int pos;                /* where the "last block" bit is in byte */
284|    int last;               /* true if processing the last block */
285|    bin *in;                /* buffered input file */
286|    unsigned char *start;   /* start of compressed data in buffer */
287|    unsigned char *junk;    /* buffer for uncompressed data -- discarded */
288|    z_off_t len;            /* length of uncompressed data (support > 4 GB) */
289|    z_stream strm;          /* zlib inflate stream */
290|
291|    /* open gzip file and skip header */
292|    in = bopen(name);
293|    if (in == NULL)
294|        bail("could not open ", name);
295|    gzhead(in);
296|
297|    /* allocate buffer for uncompressed data and initialize raw inflate
298|       stream */
299|    junk = malloc(CHUNK);
300|    strm.zalloc = Z_NULL;
301|    strm.zfree = Z_NULL;
302|    strm.opaque = Z_NULL;
303|    strm.avail_in = 0;
304|    strm.next_in = Z_NULL;
305|    ret = inflateInit2(&strm, -15);
306|    if (junk == NULL || ret != Z_OK)
307|        bail("out of memory", "");
308|
309|    /* inflate and copy compressed data, clear last-block bit if requested */
310|    len = 0;
311|    zpull(&strm, in);
312|    start = in->next;
313|    last = start[0] & 1;
314|    if (last && clr)
315|        start[0] &= ~1;
316|    strm.avail_out = 0;
317|    for (;;) {
318|        /* if input used and output done, write used input and get more */
319|        if (strm.avail_in == 0 && strm.avail_out != 0) {
320|            fwrite(start, 1, strm.next_in - start, out);
321|            start = in->buf;
322|            in->left = 0;
323|            zpull(&strm, in);
324|        }
325|
326|        /* decompress -- return early when end-of-block reached */
327|        strm.avail_out = CHUNK;
328|        strm.next_out = junk;
329|        ret = inflate(&strm, Z_BLOCK);
330|        switch (ret) {
331|        case Z_MEM_ERROR:
332|            bail("out of memory", "");
333|        case Z_DATA_ERROR:
334|            bail("invalid compressed data in ", in->name);
335|        }
336|
337|        /* update length of uncompressed data */
338|        len += CHUNK - strm.avail_out;
339|
340|        /* check for block boundary (only get this when block copied out) */
341|        if (strm.data_type & 128) {
342|            /* if that was the last block, then done */
343|            if (last)
344|                break;
345|
346|            /* number of unused bits in last byte */
347|            pos = strm.data_type & 7;
348|
349|            /* find the next last-block bit */
350|            if (pos != 0) {
351|                /* next last-block bit is in last used byte */
352|                pos = 0x100 >> pos;
353|                last = strm.next_in[-1] & pos;
354|                if (last && clr)
355|                    in->buf[strm.next_in - in->buf - 1] &= ~pos;
356|            }
357|            else {
358|                /* next last-block bit is in next unused byte */
359|                if (strm.avail_in == 0) {
360|                    /* don't have that byte yet -- get it */
361|                    fwrite(start, 1, strm.next_in - start, out);
362|                    start = in->buf;
363|                    in->left = 0;
364|                    zpull(&strm, in);
365|                }
366|                last = strm.next_in[0] & 1;
367|                if (last && clr)
368|                    in->buf[strm.next_in - in->buf] &= ~1;
369|            }
370|        }
371|    }
372|
373|    /* update buffer with unused input */
374|    in->left = strm.avail_in;
375|    in->next = in->buf + (strm.next_in - in->buf);
376|
377|    /* copy used input, write empty blocks to get to byte boundary */
378|    pos = strm.data_type & 7;
379|    fwrite(start, 1, in->next - start - 1, out);
380|    last = in->next[-1];
381|    if (pos == 0 || !clr)
382|        /* already at byte boundary, or last file: write last byte */
383|        putc(last, out);
384|    else {
385|        /* append empty blocks to last byte */
386|        last &= ((0x100 >> pos) - 1);       /* assure unused bits are zero */
387|        if (pos & 1) {
388|            /* odd -- append an empty stored block */
389|            putc(last, out);
390|            if (pos == 1)
391|                putc(0, out);               /* two more bits in block header */
392|            fwrite("\0\0\xff\xff", 1, 4, out);
393|        }
394|        else {
395|            /* even -- append 1, 2, or 3 empty fixed blocks */
396|            switch (pos) {
397|            case 6:
398|                putc(last | 8, out);
399|                last = 0;
400|            case 4:
401|                putc(last | 0x20, out);
402|                last = 0;
403|            case 2:
404|                putc(last | 0x80, out);
405|                putc(0, out);
406|            }
407|        }
408|    }
409|
410|    /* update crc and tot */
411|    *crc = crc32_combine(*crc, bget4(in), len);
412|    *tot += (unsigned long)len;
413|
414|    /* clean up */
415|    inflateEnd(&strm);
416|    free(junk);
417|    bclose(in);
418|
419|    /* write trailer if this is the last gzip file */
420|    if (!clr) {
421|        put4(*crc, out);
422|        put4(*tot, out);
423|    }
424|}

90|local int gzip_normalize(FILE *in, FILE *out, char **err) {
91|    // initialize the inflate engine to process a gzip member
92|    z_stream strm;
93|    strm.zalloc = Z_NULL;
94|    strm.zfree = Z_NULL;
95|    strm.opaque = Z_NULL;
96|    strm.avail_in = 0;
97|    strm.next_in = Z_NULL;
98|    if (inflateInit2(&strm, 15 + 16) != Z_OK)
99|        BYE("out of memory");
100|
101|    // State while processing the input gzip stream.
102|    enum {              // BETWEEN -> HEAD -> BLOCK -> TAIL -> BETWEEN -> ...
103|        BETWEEN,        // between gzip members (must end in this state)
104|        HEAD,           // reading a gzip header
105|        BLOCK,          // reading deflate blocks
106|        TAIL            // reading a gzip trailer
107|    } state = BETWEEN;              // current component being processed
108|    unsigned long crc = 0;          // accumulated CRC of uncompressed data
109|    unsigned long len = 0;          // accumulated length of uncompressed data
110|    unsigned long buf = 0;          // deflate stream bit buffer of num bits
111|    int num = 0;                    // number of bits in buf (at bottom)
112|
113|    // Write a canonical gzip header (no mod time, file name, comment, extra
114|    // block, or extra flags, and OS is marked as unknown).
115|    fwrite("\x1f\x8b\x08\0\0\0\0\0\0\xff", 1, 10, out);
116|
117|    // Process the gzip stream from in until reaching the end of the input,
118|    // encountering invalid input, or experiencing an i/o error.
119|    int more;                       // true if not at the end of the input
120|    do {
121|        // State inside this loop.
122|        unsigned char *put;         // next input buffer location to process
123|        int prev;                   // number of bits from previous block in
124|                                    // the bit buffer, or -1 if not at the
125|                                    // start of a block
126|        unsigned long long memb;    // uncompressed length of member
127|        size_t tail;                // number of trailer bytes read (0..8)
128|        unsigned long part;         // accumulated trailer component
129|
130|        // Get the next chunk of input from in.
131|        unsigned char dat[CHUNK];
132|        strm.avail_in = fread(dat, 1, CHUNK, in);
133|        if (strm.avail_in == 0)
134|            break;
135|        more = strm.avail_in == CHUNK;
136|        strm.next_in = put = dat;
137|
138|        // Run that chunk of input through the inflate engine to exhaustion.
139|        do {
140|            // At this point it is assured that strm.avail_in > 0.
141|
142|            // Inflate until the end of a gzip component (header, deflate
143|            // block, trailer) is reached, or until all of the chunk is
144|            // consumed. The resulting decompressed data is discarded, though
145|            // the total size of the decompressed data in each member is
146|            // tracked, for the calculation of the total CRC.
147|            do {
148|                // inflate and handle any errors
149|                unsigned char scrap[CHUNK];
150|                strm.avail_out = CHUNK;
151|                strm.next_out = scrap;
152|                int ret = inflate(&strm, Z_BLOCK);
153|                if (ret == Z_MEM_ERROR)
