233|                        // block bit, and check for special cases. If it is a
234|                        // stored block, then emit the header and pad to the
235|                        // next byte boundary. If it is a final, empty fixed
236|                        // block, then excise it.
237|
238|                        // Some or all of the three header bits for this block
239|                        // may already be in the bit buffer. Load any remaining
240|                        // header bits into the bit buffer.
241|                        if (num - prev < 3) {
242|                            buf += (unsigned long)*put++ << num;
243|                            num += 8;
244|                        }
245|
246|                        // Set last to have a 1 in the position of the last
247|                        // block bit in the bit buffer.
248|                        unsigned long last = (unsigned long)1 << prev;
249|
250|                        if (((buf >> prev) & 7) == 3) {
251|                            // This is a final fixed block. Load at least ten
252|                            // bits from this block, including the header, into
253|                            // the bit buffer. We already have at least three,
254|                            // so at most one more byte needs to be loaded.
255|                            if (num - prev < 10) {
