257|                                    // Need to go get and process more input.
258|                                    // We'll end up back here to finish this.
259|                                    break;
260|                                buf += (unsigned long)*put++ << num;
261|                                num += 8;
262|                            }
263|                            if (((buf >> prev) & 0x3ff) == 3) {
