311|                    // buf in front of it, leaving num bits from the end of the
312|                    // compressed data in buf when done.
313|                    unsigned char *end = strm.next_in - mix;
314|                    if (put < end) {
315|                        if (num)
316|                            // Insert num bits from buf before the data being
317|                            // copied.
318|                            do {
319|                                buf += (unsigned)(*put++) << num;
