327|                        }
328|                    }
329|
330|                    // Process the last processed byte if it wasn't written.
331|                    if (mix) {
332|                        // Load the last byte into the bit buffer.
333|                        buf += (unsigned)(*put++) << num;
334|                        num += 8;
335|
336|                        if (strm.data_type & 0x40) {
337|                            // We are at the end of the deflate stream and
338|                            // there are bits pad bits. Discard the pad bits
339|                            // and write a byte to the output, if available.
340|                            // Leave the num bits left over in buf to prepend
341|                            // to the next deflate stream.
342|                            num -= bits;
343|                            if (num >= 8) {
344|                                putc(buf, out);
345|                                num -= 8;
346|                                buf >>= 8;
347|                            }
348|
349|                            // Force the pad bits in the bit buffer to zeros.
350|                            buf &= ((unsigned long)1 << num) - 1;
