356|                            // the last byte in the bit buffer to examine on
357|                            // the next entry to BLOCK, when more bits from the
358|                            // next block will be available.
359|                            prev = num - bits;      // number of bits in buffer
360|                                                    // from current block
361|                    }
362|
363|                    // Don't have a byte left over, so we are in the middle of
364|                    // a deflate block, or the deflate block ended on a byte
365|                    // boundary. Set prev appropriately for the next entry into
366|                    // BLOCK.
367|                    else if (strm.data_type & 0x80)
368|                        // The block ended on a byte boundary, so no header
369|                        // bits are in the bit buffer.
370|                        prev = num;
371|                    else
372|                        // In the middle of a deflate block, so no header here.
373|                        prev = -1;
