409|                            // it this far, then the trailer was valid.)
410|                            if (inflateReset(&strm) != Z_OK)
411|                                BYE("internal error");
412|                            state = BETWEEN;
413|                            break;
414|                        }
415|                    } while (put < strm.next_in);
