442|    putc(crc, out);
443|    putc(crc >> 8, out);
444|    putc(crc >> 16, out);
445|    putc(crc >> 24, out);
446|    putc(len, out);
447|    putc(len >> 8, out);
448|    putc(len >> 16, out);
449|    putc(len >> 24, out);
