153|    // Decompress from in, generating access points along the way.
154|    int ret;                    // the return value from zlib, or Z_ERRNO
155|    off_t last;                 // last access point uncompressed offset
156|    do {
157|        // Assure available input, at least until reaching EOF.
158|        if (index->strm.avail_in == 0) {
159|            index->strm.avail_in = fread(buf, 1, sizeof(buf), in);
