162|            if (index->strm.avail_in < sizeof(buf) && ferror(in)) {
163|                ret = Z_ERRNO;
164|                break;
165|            }
166|
167|            if (mode == 0) {
168|                // At the start of the input -- determine the type. Assume raw
169|                // if it is neither zlib nor gzip. This could in theory result
170|                // in a false positive for zlib, but in practice the fill bits
171|                // after a stored block are always zeros, so a raw stream won't
172|                // start with an 8 in the low nybble.
173|                mode = index->strm.avail_in == 0 ? RAW :    // will fail
174|                       (index->strm.next_in[0] & 0xf) == 8 ? ZLIB :
175|                       index->strm.next_in[0] == 0x1f ? GZIP :
176|                       /* else */ RAW;
177|                index->strm.zalloc = Z_NULL;
178|                index->strm.zfree = Z_NULL;
179|                index->strm.opaque = Z_NULL;
180|                ret = inflateInit2(&index->strm, mode);
181|                if (ret != Z_OK)
182|                    break;
183|            }
184|        }
185|
186|        // Assure available output. This rotates the output through, for use as
187|        // a sliding window on the uncompressed data.
188|        if (index->strm.avail_out == 0) {
189|            index->strm.avail_out = sizeof(win);
190|            index->strm.next_out = win;
191|        }
192|
193|        if (mode == RAW && index->have == 0)
194|            // We skip the inflate() call at the start of raw deflate data in
195|            // order generate an access point there. Set data_type to imitate
196|            // the end of a header.
197|            index->strm.data_type = 0x80;
198|        else {
199|            // Inflate and update the number of uncompressed bytes.
200|            unsigned before = index->strm.avail_out;
201|            ret = inflate(&index->strm, Z_BLOCK);
202|            totout += before - index->strm.avail_out;
203|        }
204|
205|        if ((index->strm.data_type & 0xc0) == 0x80 &&
206|            (index->have == 0 || totout - last >= span)) {
207|            // We are at the end of a header or a non-last deflate block, so we
208|            // can add an access point here. Furthermore, we are either at the
209|            // very start for the first access point, or there has been span or
210|            // more uncompressed bytes since the last access point, so we want
211|            // to add an access point here.
