221|        if (ret == Z_STREAM_END && mode == GZIP &&
222|            (index->strm.avail_in || ungetc(getc(in), in) != EOF)) {
223|            // There is more input after the end of a gzip member. Reset the
224|            // inflate state to read another gzip member. On success, this will
225|            // set ret to Z_OK to continue decompressing.
226|            ret = inflateReset2(&index->strm, GZIP);
227|            beg = totout;           // reset history
228|        }
229|
230|        // Keep going until Z_STREAM_END or error. If the compressed data ends
231|        // prematurely without a file read error, Z_BUF_ERROR is returned.
232|    } while (ret == Z_OK);
