234|    if (ret != Z_STREAM_END) {
235|        // An error was encountered. Discard the index and return a negative
236|        // error code.
237|        deflate_index_free(index);
238|        return ret == Z_NEED_DICT ? Z_DATA_ERROR : ret;
239|    }
240|
241|    // Return the index.
242|    index->mode = mode;
243|    index->length = totout;
244|    *built = index;
245|    return index->have;
