283|static int inflatePreface(z_stream *strm, int bits, int value) {
284|    // Check input.
285|    if (strm == Z_NULL || bits < 0 || bits > 16)
286|        return Z_STREAM_ERROR;
287|    if (bits == 0)
288|        return Z_OK;
289|    value &= (2 << (bits - 1)) - 1;
290|
291|    // An empty dynamic block with an odd number of bits (95). The high bit of
292|    // the last byte is unused.
293|    static const unsigned char dyn[] = {
294|        4, 0xe0, 0x81, 8, 0, 0, 0, 0, 0x20, 0xa8, 0xab, 0x1f
295|    };
296|    const int dynlen = 95;          // number of bits in the block
297|
298|    // Build an input buffer for inflate that is a multiple of eight bits in
299|    // length, and that ends with the low bits bits of value.
300|    unsigned char in[(dynlen + 3 * 10 + 16 + 7) / 8];
301|    int have = 0;
302|    if (bits & 1) {
303|        // Insert an empty dynamic block to get to an odd number of bits, so
304|        // when bits bits from value are appended, we are at an even number of
305|        // bits.
306|        memcpy(in, dyn, sizeof(dyn));
307|        have = dynlen;
308|    }
309|    while ((have + bits) & 7)
310|        // Insert empty fixed blocks until appending bits bits would put us on
311|        // a byte boundary. This will insert at most three fixed blocks.
312|        append_bits(2, 10, in, &have);
313|
314|    // Append the bits bits from value, which takes us to a byte boundary.
315|    append_bits(value, bits, in, &have);
316|
317|    // Deliver the input to inflate(). There is no output space provided, but
318|    // inflate() can't get stuck waiting on output not ingesting all of the
319|    // provided input. The reason is that there will be at most 16 bits of
320|    // input from value after the empty deflate blocks (which themselves
321|    // generate no output). At least ten bits are needed to generate the first
322|    // output byte from a fixed block. The last two bytes of the buffer have to
323|    // be ingested in order to get ten bits, which is the most that value can
324|    // occupy.
325|    strm->avail_in = have >> 3;
326|    strm->next_in = in;
327|    strm->avail_out = 0;
328|    strm->next_out = in;                // not used, but can't be NULL
329|    return inflate(strm, Z_NO_FLUSH);
330|}

337|ptrdiff_t deflate_index_extract(FILE *in, struct deflate_index *index,
338|                                off_t offset, unsigned char *buf, size_t len) {
339|    // Do a quick sanity check on the index.
340|    if (index == NULL || index->have < 1 || index->list[0].out != 0 ||
341|        index->strm.state == Z_NULL)
342|        return Z_STREAM_ERROR;
343|
344|    // If nothing to extract, return zero bytes extracted.
345|    if (len == 0 || offset < 0 || offset >= index->length)
346|        return 0;
347|
348|    // Find the access point closest to but not after offset.
349|    int lo = -1, hi = index->have;
350|    point_t *point = index->list;
351|    while (hi - lo > 1) {
352|        int mid = (lo + hi) >> 1;
353|        if (offset < point[mid].out)
354|            hi = mid;
355|        else
356|            lo = mid;
357|    }
358|    point += lo;
359|
360|    // Initialize the input file and prime the inflate engine to start there.
361|    int ret = fseeko(in, point->in - (point->bits ? 1 : 0), SEEK_SET);
362|    if (ret == -1)
363|        return Z_ERRNO;
364|    int ch = 0;
365|    if (point->bits && (ch = getc(in)) == EOF)
366|        return ferror(in) ? Z_ERRNO : Z_BUF_ERROR;
367|    index->strm.avail_in = 0;
368|    ret = inflateReset2(&index->strm, RAW);
369|    if (ret != Z_OK)
370|        return ret;
371|    if (point->bits)
372|        INFLATEPRIME(&index->strm, point->bits, ch >> (8 - point->bits));
373|    inflateSetDictionary(&index->strm, point->window, point->dict);
374|
375|    // Skip uncompressed bytes until offset reached, then satisfy request.
376|    unsigned char input[CHUNK];
377|    unsigned char discard[WINSIZE];
378|    offset -= point->out;       // number of bytes to skip to get to offset
379|    size_t left = len;          // number of bytes left to read after offset
380|    do {
381|        if (offset) {
382|            // Discard up to offset uncompressed bytes.
383|            index->strm.avail_out = offset < WINSIZE ? (unsigned)offset :
384|                                                       WINSIZE;
385|            index->strm.next_out = discard;
386|        }
387|        else {
388|            // Uncompress up to left bytes into buf.
389|            index->strm.avail_out = left < (unsigned)-1 ? (unsigned)left :
390|                                                          (unsigned)-1;
391|            index->strm.next_out = buf + len - left;
392|        }
393|
394|        // Uncompress, setting got to the number of bytes uncompressed.
395|        if (index->strm.avail_in == 0) {
396|            // Assure available input.
397|            index->strm.avail_in = fread(input, 1, CHUNK, in);
398|            if (index->strm.avail_in < CHUNK && ferror(in)) {
399|                ret = Z_ERRNO;
400|                break;
401|            }
402|            index->strm.next_in = input;
403|        }
404|        unsigned got = index->strm.avail_out;
405|        ret = inflate(&index->strm, Z_NO_FLUSH);
406|        got -= index->strm.avail_out;
407|
408|        // Update the appropriate count.
409|        if (offset)
410|            offset -= got;
411|        else {
412|            left -= got;
413|            if (left == 0)
414|                // Request satisfied.
415|                break;
416|        }
417|
418|        // If we're at the end of a gzip member and there's more to read,
419|        // continue to the next gzip member.
420|        if (ret == Z_STREAM_END && index->mode == GZIP) {
421|            // Discard the gzip trailer.
422|            unsigned drop = 8;              // length of gzip trailer
423|            if (index->strm.avail_in >= drop) {
424|                index->strm.avail_in -= drop;
425|                index->strm.next_in += drop;
426|            }
427|            else {
428|                // Read and discard the remainder of the gzip trailer.
429|                drop -= index->strm.avail_in;
430|                index->strm.avail_in = 0;
431|                do {
432|                    if (getc(in) == EOF)
433|                        // The input does not have a complete trailer.
434|                        return ferror(in) ? Z_ERRNO : Z_BUF_ERROR;
435|                } while (--drop);
436|            }
437|
438|            if (index->strm.avail_in || ungetc(getc(in), in) != EOF) {
439|                // There's more after the gzip trailer. Use inflate to skip the
440|                // gzip header and resume the raw inflate there.
441|                inflateReset2(&index->strm, GZIP);
442|                do {
443|                    if (index->strm.avail_in == 0) {
444|                        index->strm.avail_in = fread(input, 1, CHUNK, in);
445|                        if (index->strm.avail_in < CHUNK && ferror(in)) {
446|                            ret = Z_ERRNO;
447|                            break;
448|                        }
449|                        index->strm.next_in = input;
450|                    }
451|                    index->strm.avail_out = WINSIZE;
452|                    index->strm.next_out = discard;
453|                    ret = inflate(&index->strm, Z_BLOCK);  // stop after header
454|                } while (ret == Z_OK && (index->strm.data_type & 0x80) == 0);
455|                if (ret != Z_OK)
456|                    break;
457|                inflateReset2(&index->strm, RAW);
458|            }
459|        }
460|
461|        // Continue until we have the requested data, the deflate data has
462|        // ended, or an error is encountered.
463|    } while (ret == Z_OK);
464|
465|    // Return the number of uncompressed bytes read into buf, or the error.
466|    return ret == Z_OK || ret == Z_STREAM_END ? len - left : ret;
467|}

93|local int gz_look(gz_statep state) {
94|    z_streamp strm = &(state->strm);
95|
96|    /* allocate read buffers and inflate memory */
97|    if (state->size == 0) {
98|        /* allocate buffers */
99|        state->in = (unsigned char *)malloc(state->want);
100|        state->out = (unsigned char *)malloc(state->want << 1);
101|        if (state->in == NULL || state->out == NULL) {
102|            free(state->out);
103|            free(state->in);
104|            gz_error(state, Z_MEM_ERROR, "out of memory");
105|            return -1;
106|        }
107|        state->size = state->want;
108|
109|        /* allocate inflate memory */
110|        state->strm.zalloc = Z_NULL;
111|        state->strm.zfree = Z_NULL;
112|        state->strm.opaque = Z_NULL;
113|        state->strm.avail_in = 0;
114|        state->strm.next_in = Z_NULL;
115|        if (inflateInit2(&(state->strm), 15 + 16) != Z_OK) {    /* gunzip */
116|            free(state->out);
117|            free(state->in);
118|            state->size = 0;
119|            gz_error(state, Z_MEM_ERROR, "out of memory");
120|            return -1;
121|        }
122|    }
123|
124|    /* if transparent reading is disabled, which would only be at the start, or
125|       if we're looking for a gzip member after the first one, which is not at
126|       the start, then proceed directly to look for a gzip member next */
127|    if (state->direct == -1 || state->junk == 0) {
128|        /* wait for input before committing to another gzip member */
129|        if (state->junk == 0 && strm->avail_in == 0) {
130|            if (gz_avail(state) == -1)
131|                return -1;
132|            if (strm->avail_in == 0)
133|                return 0;
134|        }
135|        inflateReset(strm);
136|        state->how = GZIP;
137|        state->junk = state->junk != -1;
138|        state->direct = 0;
139|        return 0;
140|    }
141|
142|    /* otherwise we're at the start with auto-detect -- we check to see if the
143|       first four bytes could be gzip header in order to decide whether or not
144|       this will be a transparent read */
145|
146|    /* load any header bytes into the input buffer -- if the input is empty,
147|       then it's not an error as this is a transparent read of zero bytes */
148|    if (gz_avail(state) == -1)
149|        return -1;
150|    if (strm->avail_in == 0 || (state->again && strm->avail_in < 4))
151|        /* if non-blocking input stalled before getting four bytes, then
152|           return and wait until a later call has accumulated enough */
153|        return 0;
154|
155|    /* see if this is (likely) gzip input -- if the first four bytes are
156|       consistent with a gzip header, then go look for the first gzip member,
157|       otherwise proceed to copy the input transparently */
158|    if (strm->avail_in > 3 &&
159|            strm->next_in[0] == 31 && strm->next_in[1] == 139 &&
160|            strm->next_in[2] == 8 && strm->next_in[3] < 32) {
161|        inflateReset(strm);
162|        state->how = GZIP;
163|        state->junk = 1;
164|        state->direct = 0;
165|        return 0;
166|    }
167|
168|    /* doing raw i/o: copy any leftover input to output -- this assumes that
169|       the output buffer is larger than the input buffer, which also assures
170|       space for gzungetc() */
171|    state->x.next = state->out;
172|    memcpy(state->x.next, strm->next_in, strm->avail_in);
173|    state->x.have = strm->avail_in;
174|    strm->avail_in = 0;
175|    state->how = COPY;
176|    return 0;
177|}

187|local int gz_decomp(gz_statep state) {
188|    int ret = Z_OK;
189|    unsigned had;
190|    z_streamp strm = &(state->strm);
191|
192|    /* fill output buffer up to end of deflate stream */
193|    had = strm->avail_out;
194|    do {
195|        /* get more input for inflate() */
196|        if (strm->avail_in == 0 && gz_avail(state) == -1) {
197|            ret = state->err;
198|            break;
199|        }
200|        if (strm->avail_in == 0) {
201|            if (!state->again)
202|                gz_error(state, Z_BUF_ERROR, "unexpected end of file");
203|            break;
204|        }
205|
206|        /* decompress and handle errors */
207|        ret = inflate(strm, Z_NO_FLUSH);
208|        if (strm->avail_out < had)
209|            /* any decompressed data marks this as a real gzip stream */
210|            state->junk = 0;
211|        if (ret == Z_STREAM_ERROR || ret == Z_NEED_DICT) {
212|            gz_error(state, Z_STREAM_ERROR,
213|                     "internal error: inflate stream corrupt");
214|            break;
215|        }
216|        if (ret == Z_MEM_ERROR) {
217|            gz_error(state, Z_MEM_ERROR, "out of memory");
218|            break;
219|        }
220|        if (ret == Z_DATA_ERROR) {              /* deflate stream invalid */
221|            if (state->junk == 1) {             /* trailing garbage is ok */
222|                strm->avail_in = 0;
223|                state->eof = 1;
224|                state->how = LOOK;
225|                ret = Z_OK;
226|                break;
227|            }
228|            gz_error(state, Z_DATA_ERROR,
229|                     strm->msg == NULL ? "compressed data error" : strm->msg);
230|            break;
231|        }
232|    } while (strm->avail_out && ret != Z_STREAM_END);
233|
234|    /* update available output */
235|    state->x.have = had - strm->avail_out;
236|    state->x.next = strm->next_out - state->x.have;
237|
238|    /* if the gzip stream completed successfully, look for another */
239|    if (ret == Z_STREAM_END) {
240|        state->junk = 0;
241|        state->how = LOOK;
242|        return 0;
243|    }
244|
245|    /* return decompression status */
246|    return ret != Z_OK ? -1 : 0;
247|}

25|int ZEXPORT inflateBackInit_(z_streamp strm, int windowBits,
