206|        {16, 17, 18, 0, 8, 7, 9, 6, 10, 5, 11, 4, 12, 3, 13, 2, 14, 1, 15};
207|
208|    /* Check that the strm exists and that the state was initialized */
209|    if (strm == Z_NULL || strm->state == Z_NULL)
210|        return Z_STREAM_ERROR;
