226|    for (;;)
227|        switch (state->mode) {
228|        case TYPE:
229|            /* determine and dispatch block type */
230|            if (state->last) {
231|                BYTEBITS();
232|                state->mode = DONE;
233|                break;
234|            }
235|            NEEDBITS(3);
236|            state->last = BITS(1);
237|            DROPBITS(1);
238|            switch (BITS(2)) {
239|            case 0:                             /* stored block */
240|                Tracev((stderr, "inflate:     stored block%s\n",
