257|                state->mode = BAD;
258|            }
259|            DROPBITS(2);
260|            break;
261|
262|        case STORED:
263|            /* get and verify stored block length */
264|            BYTEBITS();                         /* go to byte boundary */
265|            NEEDBITS(32);
266|            if ((hold & 0xffff) != ((hold >> 16) ^ 0xffff)) {
267|                strm->msg = (z_const char *)"invalid stored block lengths";
